package video

import (
	"context"
	"myapp/storage"
	"myapp/transcoder"
)

type TranscodeTask struct {
	VideoID          string
	TargetResolution string
	DestinationS3    string
	SubmittedByOrgID string
}

type TranscodeWorker struct {
	Storage    storage.Client
	Transcoder transcoder.Engine
}

func (w *TranscodeWorker) ExecuteTask(ctx context.Context, task TranscodeTask) error {
	// BOLA: Background worker fetches video source file directly by VideoID
	// and transcodes output into DestinationS3 without checking video ownership.
	srcPath, err := w.Storage.GetVideoSourcePath(ctx, task.VideoID)
	if err != nil {
		return err
	}

	return w.Transcoder.Process(ctx, srcPath, task.DestinationS3, task.TargetResolution)
}

corrected_code:
package video

import (
	"context"
	"errors"
	"myapp/storage"
	"myapp/transcoder"
)

type TranscodeTask struct {
	VideoID          string
	TargetResolution string
	DestinationS3    string
	SubmittedByOrgID string
}

type TranscodeWorker struct {
	Storage    storage.Client
	Transcoder transcoder.Engine
}

func (w *TranscodeWorker) ExecuteTask(ctx context.Context, task TranscodeTask) error {
	owned, err := w.Storage.VerifyVideoOwnership(ctx, task.VideoID, task.SubmittedByOrgID)
	if err != nil || !owned {
		return errors.New("transcode worker: unauthorized video access denied")
	}

	srcPath, err := w.Storage.GetVideoSourcePath(ctx, task.VideoID)
	if err != nil {
		return err
	}

	return w.Transcoder.Process(ctx, srcPath, task.DestinationS3, task.TargetResolution)
}
